/**
 * ToolCallNode — 工具调用/结果节点渲染。
 *
 * 借鉴 deepseek-harness 的 ToolCallTree 递归模式：
 * - 展示工具名称、状态、耗时
 * - 支持展开/折叠参数与结果
 * - 支持子调用嵌套（sub_calls）
 */
import { useState } from 'react'
import { cn } from '@/lib/utils'
import {
  ChevronRight, ChevronDown, Wrench, CheckCircle2,
  XCircle, Loader2, Clock, AlertTriangle,
} from 'lucide-react'
import type { ToolCallData } from '../types'

interface Props {
  callId: string
  name: string
  args?: Record<string, unknown>
  result?: string
  isError?: boolean
  status?: ToolCallData['status']
  durationMs?: number
  subCalls?: ToolCallData[]
  depth?: number
}

const statusIcons: Record<string, typeof CheckCircle2> = {
  running: Loader2,
  completed: CheckCircle2,
  error: XCircle,
  timeout: Clock,
}

const statusColors: Record<string, string> = {
  running: 'text-blue-500',
  completed: 'text-green-500',
  error: 'text-red-500',
  timeout: 'text-yellow-500',
}

export function ToolCallNode({
  callId, name, args, result, isError, status = 'completed',
  durationMs, subCalls, depth = 0,
}: Props) {
  const [expanded, setExpanded] = useState(false)

  const Icon = statusIcons[status] || (isError ? XCircle : Wrench)
  const iconColor = isError ? statusColors.error : statusColors[status] || 'text-muted-foreground'
  const isRunning = status === 'running'

  return (
    <div
      className="tool-call-node"
      style={{ marginLeft: depth > 0 ? 16 : 0 }}
    >
      {/* 主行 */}
      <div
        className={cn(
          'flex items-center gap-2 rounded-lg border px-3 py-2 text-sm cursor-pointer transition-colors hover:bg-accent/50',
          isError && 'border-red-200 dark:border-red-900 bg-red-50/50 dark:bg-red-950/20',
          isRunning && 'border-blue-200 dark:border-blue-900 bg-blue-50/50 dark:bg-blue-950/20',
        )}
        onClick={() => setExpanded(!expanded)}
      >
        {/* 展开/折叠 */}
        {(args || result || subCalls?.length) ? (
          expanded
            ? <ChevronDown className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
            : <ChevronRight className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
        ) : (
          <span className="w-3.5" />
        )}

        {/* 状态图标 */}
        <Icon className={cn('h-4 w-4 shrink-0', iconColor, isRunning && 'animate-spin')} />

        {/* 工具名称 */}
        <span className="font-mono text-xs font-medium">{name}</span>

        {/* 耗时 */}
        {durationMs != null && (
          <span className="ml-auto text-xs text-muted-foreground tabular-nums">
            {durationMs}ms
          </span>
        )}

        {/* 状态标签 */}
        {isError && (
          <AlertTriangle className="h-3.5 w-3.5 text-red-500" />
        )}
      </div>

      {/* 展开详情 */}
      {expanded && (
        <div className="ml-5 mt-1 space-y-2 border-l-2 border-muted pl-3">
          {/* 参数 */}
          {args && Object.keys(args).length > 0 && (
            <div>
              <div className="text-xs font-medium text-muted-foreground mb-1">参数</div>
              <pre className="rounded-md bg-muted/50 p-2 text-xs overflow-x-auto whitespace-pre-wrap break-all">
                {JSON.stringify(args, null, 2)}
              </pre>
            </div>
          )}

          {/* 结果 */}
          {result && (
            <div>
              <div className="text-xs font-medium text-muted-foreground mb-1">
                {isError ? '错误' : '结果'}
              </div>
              <pre className={cn(
                'rounded-md p-2 text-xs overflow-x-auto whitespace-pre-wrap break-all',
                isError ? 'bg-red-50/50 dark:bg-red-950/20 text-red-700 dark:text-red-400' : 'bg-muted/50',
              )}>
                {result.length > 2000 ? result.slice(0, 2000) + '\n... (已截断)' : result}
              </pre>
            </div>
          )}

          {/* 子调用树 */}
          {subCalls && subCalls.length > 0 && (
            <div>
              <div className="text-xs font-medium text-muted-foreground mb-1">
                子调用 ({subCalls.length})
              </div>
              <div className="space-y-1">
                {subCalls.map((sub) => (
                  <ToolCallNode
                    key={sub.call_id}
                    callId={sub.call_id}
                    name={sub.name}
                    args={sub.args}
                    result={sub.result}
                    status={sub.status}
                    durationMs={sub.duration_ms}
                    subCalls={sub.sub_calls}
                    depth={depth + 1}
                  />
                ))}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  )
}
